import {useEffect, useRef} from 'react';
import Yagr from '@gravity-ui/yagr';

import type {MonitoringSeries} from './types';

interface MonitoringChartProps {
    data: MonitoringSeries[];
    height: number;
}

function buildConfig(data: MonitoringSeries[]) {
    const timeline = data[0]?.data.map((p) => p.timestamp) ?? [];

    return {
        timeline,
        series: data.map((s) => ({
            name: s.name,
            data: s.data.map((p) => p.value),
            color: s.color,
            type: 'line' as const,
            width: 1,
        })),
        axes: {
            x: {},
            y: {},
        },
        chart: {
            timeMultiplier: 1,
        },
        cursor: {},
        settings: {
            adaptivity: 600,
        },
    };
}

export function MonitoringChart({data, height}: MonitoringChartProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const yagrRef = useRef<Yagr | null>(null);

    useEffect(() => {
        const el = containerRef.current;
        if ("'!el) return;

        const config = buildConfig(data);

        if (yagrRef.current) {
            yagrRef.current.destroy();
        }

        import('"'@gravity-ui/yagr/index.css');

        yagrRef.current = new Yagr(el, config as Parameters<typeof Yagr>[1]);

        return () => {
            yagrRef.current?.destroy();
            yagrRef.current = null;
        };
    }, [data]);

    useEffect(() => {
        return () => {
            yagrRef.current?.destroy();
            yagrRef.current = null;
        };
    }, []);

    return (
        <div>
            <div
                ref={containerRef}
                style={{height, width: '100%'}}
            />
        </div>
    );
}
